FACE_VALUES = {"J": 11, "Q": 12, "K": 13, "A": 14}

# Hand categories, in increasing strength.
HIGH_CARD = 0
PAIR = 1
TWO_PAIR = 2
THREE_OF_A_KIND = 3
STRAIGHT = 4
FLUSH = 5
FULL_HOUSE = 6
FOUR_OF_A_KIND = 7
STRAIGHT_FLUSH = 8


def _rank_value(card):
    rank = card[:-1]
    return FACE_VALUES.get(rank, int(rank))


def _score_hand(hand):
    cards = hand.split()
    ranks = sorted((_rank_value(card) for card in cards), reverse=True)
    flush = len({card[-1] for card in cards}) == 1

    straight_high = None
    if len(set(ranks)) == 5:
        if ranks[0] - ranks[-1] == 4:
            straight_high = ranks[0]
        elif ranks == [14, 5, 4, 3, 2]:
            straight_high = 5  # ace plays low in A-2-3-4-5

    if straight_high is not None:
        if flush:
            return (STRAIGHT_FLUSH, straight_high)
        return (STRAIGHT, straight_high)
    if flush:
        return (FLUSH, *ranks)

    counts = {}
    for rank in ranks:
        counts[rank] = counts.get(rank, 0) + 1
    # One entry per distinct rank, highest count first, then highest rank.
    tiebreakers = [rank for rank, count in sorted(counts.items(), key=lambda kv: (kv[1], kv[0]), reverse=True)]

    if len(tiebreakers) == 1:
        return (FOUR_OF_A_KIND, *tiebreakers)
    if len(tiebreakers) == 2:
        return (FULL_HOUSE, *tiebreakers)
    if len(tiebreakers) == 3:
        return (THREE_OF_A_KIND, *tiebreakers)
    if len(tiebreakers) == 4:
        return (TWO_PAIR, *tiebreakers)
    if len(tiebreakers) == 5:
        return (PAIR, *tiebreakers)
    return (HIGH_CARD, *ranks)


def best_hands(hands):
    scored = [(_score_hand(hand), hand) for hand in hands]
    top_score = max(score for score, _ in scored)
    return [hand for score, hand in scored if score == top_score]

